const ValueList: FC<{
	values: unknown[];
	openLink: (href: string) => void;
	depth: number;
	stateKey: string;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}> = ({ values, openLink, depth, stateKey, viewState, onViewStateChange }) => {
	const pageSize = 10;
	const restoredPage = viewState?.[`${stateKey}.page`];
	const [localPage, setLocalPage] = useState(
		typeof restoredPage === "number" ? Math.max(0, restoredPage) : 0,
	);
	const pageCount = Math.max(1, Math.ceil(values.length / pageSize));
	const requestedPage =
		typeof restoredPage === "number" ? Math.max(0, restoredPage) : localPage;
	const page = Math.min(requestedPage, pageCount - 1);
	const changePage = (next: number) => {
		setLocalPage(next);
		onViewStateChange?.(`${stateKey}.page`, next);
	};
	const visible = values.slice(page * pageSize, (page + 1) * pageSize);
	return (
		<div>
			<div className="space-y-2">
				{visible.map((item, index) => (
					// biome-ignore lint/suspicious/noArrayIndexKey: arbitrary result arrays may contain duplicate, identity-less values and are immutable here.
					<div key={`${page}:${index}:${compactValue(item).slice(0, 30)}`}>
						<ValueView
							value={item}
							openLink={openLink}
							depth={depth + 1}
							stateKey={`${stateKey}.${page * pageSize + index}`}
							viewState={viewState}
							onViewStateChange={onViewStateChange}
						/>
					</div>
				))}
			</div>
			{pageCount > 1 ? (
				<Pagination page={page} pageCount={pageCount} onChange={changePage} />
			) : null}
		</div>
	);
};

const ValueView: FC<{
	value: unknown;
	openLink: (href: string) => void;
	depth?: number;
	stateKey?: string;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}> = ({
	value,
	openLink,
	depth = 0,
	stateKey = "value",
	viewState,
	onViewStateChange,
}) => {
	if (typeof value === "string")
		return <LinkValue value={value} openLink={openLink} />;
	if (value === null || value === undefined || typeof value !== "object") {
		return <span className="break-words text-sm">{compactValue(value)}</span>;
	}
	if (depth >= 5) {
		return (
			<pre className="overflow-x-auto whitespace-pre-wrap text-xs">
				{stringify(value)}
			</pre>
		);
	}
	if (Array.isArray(value)) {
		if (value.length === 0)
			return <span className="text-muted-foreground text-xs">Empty</span>;
		const records = value.filter(isRecord);
		if (
			records.length === value.length &&
			records.every((record) => looksLikeEntity(record))
		) {
			const entityRows = records.map((entity) => {
				const metadata = isRecord(entity.metadata) ? entity.metadata : null;
				const link = [entity.view_url, entity.url, entity.source_url].find(
					isExternalHttpUrl,
				);
				return {
					name: entity.name,
					type: humanize(
						String(
							entity.entity_type ??
								entity.entity_type_name ??
								entity.type ??
								"Entity",
						),
					),
					id: entity.id,
					...(metadata && Object.keys(metadata).length > 0 ? { metadata } : {}),
					...(link ? { open: link } : {}),
				};
			});
			const entityColumns = ["name", "type", "id"];
			if (entityRows.some((row) => "metadata" in row)) {
				entityColumns.push("metadata");
			}
			if (entityRows.some((row) => "open" in row)) entityColumns.push("open");
			return (
				<DataTable
					rows={entityRows}
					columns={entityColumns.map((name) => ({ name }))}
					openLink={openLink}
					stateKey={`${stateKey}.entities`}
					viewState={viewState}
					onViewStateChange={onViewStateChange}
				/>
			);
		}
		if (
			records.length === value.length &&
			!records.some(
				(record) => looksLikeEvent(record) || looksLikeEntity(record),
			)
		) {
			return (
				<DataTable
					rows={records}
					openLink={openLink}
					stateKey={`${stateKey}.table`}
					viewState={viewState}
					onViewStateChange={onViewStateChange}
				/>
			);
		}
		return (
			<ValueList
				values={value}
				openLink={openLink}
				depth={depth}
				stateKey={stateKey}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	}
	if (!isRecord(value))
		return <span className="text-sm">Unsupported value</span>;
	if (looksLikeEvent(value))
		return (
			<EventView
				event={value}
				openLink={openLink}
				stateKey={stateKey}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	if (looksLikeEntity(value))
		return (
			<EntityView
				entity={value}
				openLink={openLink}
				stateKey={stateKey}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	return (
		<dl className="grid gap-1.5">
			{Object.entries(value).map(([key, inner]) => (
				<div
					key={key}
					className="grid grid-cols-[minmax(6rem,0.35fr)_1fr] gap-2 text-xs"
				>
					<dt className="break-words font-medium text-muted-foreground">
						{humanize(key)}
					</dt>
					<dd className="min-w-0">
						<ValueView
							value={inner}
							openLink={openLink}
							depth={depth + 1}
							stateKey={`${stateKey}.${key}`}
							viewState={viewState}
							onViewStateChange={onViewStateChange}
						/>
					</dd>
				</div>
			))}
		</dl>
	);
};

function DataTable({
	rows,
	columns,
	openLink,
	stateKey = "table",
	viewState,
	onViewStateChange,
}: {
	rows: UnknownRecord[];
	columns?: Array<{ name: string; type?: string }>;
	openLink: (href: string) => void;
	stateKey?: string;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}) {
	const restoredPage = viewState?.[`${stateKey}.page`];
	const [localPage, setLocalPage] = useState(
		typeof restoredPage === "number" ? Math.max(0, restoredPage) : 0,
	);
	const pageSize = 10;
	const names = useMemo(
		() =>
			columns?.map((column) => column.name) ??
			[...new Set(rows.flatMap((row) => Object.keys(row)))].slice(0, 12),
		[columns, rows],
	);
	const restoredSortColumn = viewState?.[`${stateKey}.sort.column`];
	const restoredSortDesc = viewState?.[`${stateKey}.sort.desc`];
	const restoredSorting: SortingState =
		typeof restoredSortColumn === "string" && restoredSortColumn
			? [{ id: restoredSortColumn, desc: restoredSortDesc === true }]
			: [];
	const [sorting, setSorting] = useState<SortingState>(restoredSorting);
	useEffect(() => {
		setSorting(restoredSorting);
	}, [restoredSortColumn, restoredSortDesc]);
	useEffect(() => {
		setLocalPage(
			typeof restoredPage === "number" ? Math.max(0, restoredPage) : 0,
		);
	}, [restoredPage]);
	const pageCount = Math.max(1, Math.ceil(rows.length / pageSize));
	const page = Math.min(localPage, pageCount - 1);
	const changePage = (next: number) => {
		setLocalPage(next);
		onViewStateChange?.(`${stateKey}.page`, next);
	};
	const tableColumns = useMemo<ColumnDef<UnknownRecord>[]>(
		() =>
			names.map((name) => ({
				id: name,
				accessorFn: (row) => row[name],
				header: humanize(name),
				enableSorting: name !== "open",
				sortDescFirst: false,
				sortingFn: (rowA, rowB, columnId) => {
					const a = rowA.getValue(columnId);
					const b = rowB.getValue(columnId);
					if (typeof a === "number" && typeof b === "number") return a - b;
					return compactValue(a).localeCompare(compactValue(b), undefined, {
						numeric: true,
						sensitivity: "base",
					});
				},
				cell: ({ getValue, row }) => {
					const cell = getValue();
					if (name === "open" && typeof cell === "string") {
						return (
							<Button
								type="button"
								variant="ghost"
								size="sm"
								className="h-7 px-2"
								onClick={() => openLink(cell)}
							>
								<ExternalLink className="mr-1 h-3.5 w-3.5" />
								Open
							</Button>
						);
					}
					return isRecord(cell) || Array.isArray(cell) ? (
						<PersistentDetails
							summary="Structured value"
							stateKey={`${stateKey}.row-${row.index}.cell-${name}.open`}
							viewState={viewState}
							onViewStateChange={onViewStateChange}
						>
							<pre className="mt-1 max-h-56 overflow-auto whitespace-pre-wrap">
								{stringify(cell)}
							</pre>
						</PersistentDetails>
					) : (
						<ValueView value={cell} openLink={openLink} depth={1} />
					);
				},
			})),
		[names, onViewStateChange, openLink, stateKey, viewState],
	);
	const table = useReactTable({
		data: rows,
		columns: tableColumns,
		state: { sorting, pagination: { pageIndex: page, pageSize } },
		onSortingChange: (updater) => {
			const next = typeof updater === "function" ? updater(sorting) : updater;
			setSorting(next);
			changePage(0);
			onViewStateChange?.(`${stateKey}.sort.column`, next[0]?.id ?? "");
			onViewStateChange?.(`${stateKey}.sort.desc`, next[0]?.desc ?? false);
		},
		getCoreRowModel: getCoreRowModel(),
		getSortedRowModel: getSortedRowModel(),
		getPaginationRowModel: getPaginationRowModel(),
	});
	return (
		<div>
			<div className="overflow-hidden rounded-md border border-border/70">
				<Table className="text-xs">
					<TableHeader className="bg-muted/50">
						{table.getHeaderGroups().map((headerGroup) => (
							<TableRow key={headerGroup.id} className="hover:bg-transparent">
								{headerGroup.headers.map((header) => {
									const sorted = header.column.getIsSorted();
									const label = String(header.column.columnDef.header);
									const canSort = header.column.getCanSort();
									return (
										<TableHead
											key={header.id}
											aria-sort={
												!canSort
													? undefined
													: sorted === "asc"
													? "ascending"
													: sorted === "desc"
														? "descending"
														: "none"
											}
											className="h-8 whitespace-nowrap px-2"
										>
											{canSort ? (
												<button
													type="button"
													aria-label={`Sort by ${label}`}
													className="flex w-full items-center gap-1.5 text-left"
													onClick={header.column.getToggleSortingHandler()}
												>
													{flexRender(
														header.column.columnDef.header,
														header.getContext(),
													)}
													{sorted === "asc" ? (
														<ArrowUp className="h-3 w-3" />
													) : sorted === "desc" ? (
														<ArrowDown className="h-3 w-3" />
													) : (
														<ArrowUpDown className="h-3 w-3 opacity-45" />
													)}
												</button>
							</TableRow>
						))}
					</TableHeader>
					<TableBody>
						{table.getRowModel().rows.map((row) => (
							<TableRow key={row.id}>
								{row.getVisibleCells().map((cell) => (
									<TableCell
										key={cell.id}
										className="max-w-80 p-2 align-top"
									>
										{flexRender(cell.column.columnDef.cell, cell.getContext())}
									</TableCell>
								))}
							</TableRow>
						))}
					</TableBody>
				</Table>
			</div>
			{pageCount > 1 ? (
				<Pagination page={page} pageCount={pageCount} onChange={changePage} />
			) : null}
		</div>
	);
}

const RawResult: FC<{
	value: unknown;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}> = ({ value, viewState, onViewStateChange }) => {
	const [copyStatus, setCopyStatus] = useState<"idle" | "copied" | "failed">(
		"idle",
	);
	const json = stringify(value);
	return (
		<PersistentDetails
			summary="Raw result"
			stateKey="details.raw.open"
			viewState={viewState}
			onViewStateChange={onViewStateChange}
			className={cn(FILLED_BOX, "px-3 py-2 text-xs")}
		>
			<div className="mt-2">
				<div className="mb-2 flex justify-end">
					<Button
						type="button"
						variant="outline"
						size="sm"
						onClick={() => {
							if (!navigator.clipboard) {
								setCopyStatus("failed");
								return;
							}
							void navigator.clipboard
								.writeText(json)
								.then(() => setCopyStatus("copied"))
								.catch(() => setCopyStatus("failed"));
						}}
					>
						{copyStatus === "copied"
							? "Copied"
							: copyStatus === "failed"
								? "Copy failed"
								: "Copy JSON"}
					</Button>
				</div>
				<pre className="max-h-80 overflow-auto whitespace-pre-wrap rounded-md border border-border/70 bg-background/40 p-2">
					{json}
				</pre>
			</div>
		</PersistentDetails>
	);
};

interface SdkMethodDoc {
	path: string;
	namespace: string;
	summary: string;
	access?: string;
	details: string[];
}

function parseSdkMethodDoc(value: string): SdkMethodDoc {
	const lines = value.split("\n");
	const listParts = lines[0]?.split(/\s+—\s+/, 2) ?? [];
	const path = (listParts[0] ?? "SDK method").trim();
	const detailLines = lines
		.slice(1)
		.map((line) => line.trim())
		.filter(Boolean);
	const accessLine = detailLines.find((line) => line.startsWith("access:"));
	const summary =
		listParts[1]?.trim() ||
		detailLines.find(
			(line) =>
				!line.startsWith("access:") &&
				!line.startsWith("signature:") &&
				!line.startsWith("example:") &&
				line !== "usage_example:",
		) ||
		"SDK method";
	const details = detailLines.filter(
		(line) => line !== summary && !line.startsWith("access:"),
	);
	return {
		path,
		namespace: path.includes(".") ? path.split(".")[0] : "Related",
		summary,
		access: accessLine?.slice("access:".length).trim().split(" ")[0],
		details,
	};
}

const SdkSearchResult: FC<{
	value: UnknownRecord;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}> = ({ value, viewState, onViewStateChange }) => {
	const methods = (value.results as unknown[])
		.filter((result): result is string => typeof result === "string")
		.map(parseSdkMethodDoc);
	const groupedMap = new Map<string, SdkMethodDoc[]>();
	for (const method of methods) {
		const entries = groupedMap.get(method.namespace) ?? [];
		entries.push(method);
		groupedMap.set(method.namespace, entries);
	}
	const grouped = [...groupedMap.entries()].sort(([a], [b]) =>
		a.localeCompare(b),
	);
	return (
		<Section title="SDK methods" meta={`${String(value.match_count)} matches`}>
			<div className="mb-3 flex flex-wrap items-center gap-2 text-xs">
				<span className="text-muted-foreground">Search</span>
				<code className="rounded bg-muted px-1.5 py-0.5">
					{String(value.query)}
				</code>
			</div>
			<div className="space-y-4">
				{grouped.map(([namespace, entries]) => (
					<div key={namespace}>
						<h3 className="mb-1.5 font-mono text-[10px] uppercase tracking-wide text-muted-foreground">
							{humanize(namespace)}
						</h3>
						<div className="divide-y divide-border/60 rounded-md border border-border/70 bg-background/40">
							{(entries ?? []).map((method) => (
								<div key={method.path} className="p-2.5">
									<div className="flex flex-wrap items-start justify-between gap-2">
										<div className="min-w-0">
											<code className="break-all font-medium text-xs">
												{method.path}
											</code>
											<p className="mt-0.5 text-muted-foreground text-xs">
												{method.summary}
											</p>
										</div>
										{method.access ? (
											<span className="rounded-full border border-border px-2 py-0.5 text-[10px] text-muted-foreground">
												{humanize(method.access)}
											</span>
										) : null}
									</div>
									{method.details.length > 0 ? (
										<PersistentDetails
											summary="Method details"
											stateKey={`sdk-method.${method.path}.open`}
											viewState={viewState}
											onViewStateChange={onViewStateChange}
											className="mt-2 text-xs text-muted-foreground"
										>
											<pre className="mt-2 overflow-x-auto whitespace-pre-wrap rounded-md bg-muted/40 p-2 text-foreground">
												{method.details.join("\n")}
											</pre>
										</PersistentDetails>
									) : null}
								</div>
							))}
						</div>
					</div>
				))}
			</div>
			{typeof value.notes === "string" ? (
				<p className="mt-3 text-muted-foreground text-xs">{value.notes}</p>
			) : null}
		</Section>
	);
};

function isSqlResult(value: UnknownRecord): boolean {
	return (
		Array.isArray(value.rows) &&
		Array.isArray(value.columns) &&
		typeof value.total_count === "number"
	);
}

const SqlResult: FC<{
	value: UnknownRecord;
	openLink: (href: string) => void;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}> = ({ value, openLink, viewState, onViewStateChange }) => {
	const rows = (value.rows as unknown[]).filter(isRecord);
	const columns = (value.columns as unknown[])
		.filter(isRecord)
		.filter((column) => typeof column.name === "string")
		.map((column) => ({
			name: String(column.name),
			type: String(column.type ?? ""),
		}));
	const meta = `${String(value.total_count)} rows · ${String(value.execution_time_ms ?? 0)} ms`;
	return (
		<Section title="SQL results" meta={meta}>
			{typeof value.error === "string" ? (
				<div className="mb-2 rounded-md border border-destructive/40 bg-destructive/10 p-2 text-sm text-destructive">
					{value.error}
				</div>
			) : null}
			{typeof value.sql === "string" && value.sql.trim() ? (
				<PersistentDetails
					summary="SQL query"
					stateKey="details.sql-query.open"
					viewState={viewState}
					onViewStateChange={onViewStateChange}
					className="mb-3 text-xs text-muted-foreground"
				>
					<pre className="mt-2 max-h-56 overflow-auto whitespace-pre-wrap rounded-md border border-border/70 bg-muted/40 p-2 text-foreground">
						<code>{value.sql}</code>
					</pre>
				</PersistentDetails>
			) : null}
			<DataTable
				rows={rows}
				columns={columns}
				openLink={openLink}
				stateKey="table.sql"
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
			{value.has_more === true ? (
				<p className="mt-2 text-muted-foreground text-xs">
					More rows are available from the server.
				</p>
			) : null}
		</Section>
	);
};

function isSdkResult(value: UnknownRecord): boolean {
	return typeof value.success === "boolean" && Array.isArray(value.logs);
}

function hasPurposeCollections(value: UnknownRecord): boolean {
	return (
		Array.isArray(value.events) ||
		Array.isArray(value.entities) ||
		Array.isArray(value.rows)
	);
}

